import '../models/dhikr_model.dart';

class AthkarData {
  static List<DhikrModel> getByCategory(DhikrCategory category) {
    switch (category) {
      case DhikrCategory.morning:
        return _morningAthkar;
      case DhikrCategory.evening:
        return _eveningAthkar;
      case DhikrCategory.sleep:
        return _sleepAthkar;
      case DhikrCategory.wakeup:
        return _wakeupAthkar;
      case DhikrCategory.prayer:
        return _prayerAthkar;
      case DhikrCategory.afterPrayer:
        return _afterPrayerAthkar;
      case DhikrCategory.mosque:
        return _mosqueAthkar;
      case DhikrCategory.food:
        return _foodAthkar;
      case DhikrCategory.travel:
        return _travelAthkar;
      case DhikrCategory.quran:
        return _quranAthkar;
      case DhikrCategory.names:
        return _namesAthkar;
      case DhikrCategory.misc:
        return _miscAthkar;
      case DhikrCategory.ruqyah:
        return _ruqyahAthkar;
      case DhikrCategory.nawawi40:
        return _nawawi40Athkar;
      case DhikrCategory.dailySunnah:
        return _dailySunnahAthkar;
      case DhikrCategory.fridaySunnah:
        return _fridaySunnahAthkar;
      case DhikrCategory.prophetsDua:
        return _prophetsDuaAthkar;
    }
  }

  /// "المحتوى المتجدد" في الشاشة الرئيسية: يتغيّر تلقائياً كل ٤ ساعات
  /// تقريباً (لا عشوائياً عند كل فتح)، مأخوذ دائماً من محتوى مُتحقَّق منه
  /// فعلياً وموجود أصلاً في التطبيق (لا نص جديد غير موثّق).
  static DhikrModel rotatingContent([DateTime? at]) {
    final now = at ?? DateTime.now();
    final pool = <DhikrModel>[
      ..._quranAthkar,
      ..._miscAthkar,
      ..._namesAthkar,
      ..._afterPrayerAthkar,
    ];
    if (pool.isEmpty) return _miscAthkar.first;
    final epochHour = now.millisecondsSinceEpoch ~/ (1000 * 60 * 60);
    final bucket = epochHour ~/ 4;
    return pool[bucket % pool.length];
  }

